style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/3tvNKQ3.png") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Optional: Make main containers slightly see-through */
    .container-main,
    .navbar,
    .footer,
    .content,
    #navigation,
    #header,
    .nav-menu {
        background: rgba(0, 0, 0, 0.6) !important;
        color: #fff !important;
    }

    /* Optional: Transparent white outlines on buttons/inputs */
    input,
    button {
        background-color: rgba(255, 255, 255, 0.1) !important;
        color: #ffffff !important;
        border: 1px solid #ffffff !important;
    }

    /* Optional: Hide ads or empty divs */
    .ad-container,
    .ads,
    [id^="advertisement"] {
        display: none !important;
    }
}
